/* C0/99DE — player map-rect velocity clamp. DP=$1D00 (TCD #$1D00 at C0/885D).
   Runs at C0/884F, AFTER 9175 (writes $32/$33 APPLIED) and BEFORE 91AC accel / 93E1 integrate.
   Operates on the signed 8-bit velocity ACCUMULATORS vx=$1D2E, vy=$1D30; zeroes one when the
   directional leaf returns CARRY=blocked. 8-bit A, 8-bit X. All "$XX" = $7E:1DXX. */

/* --- foot/bound/subtile WRAM (DP $1D00) ---
   $0A/$0C : X left/right foot, HALF-tile units (>>1 = tile). $0E/$10 : Y up/down foot, half-tile.
   $1A=left bound, $1B=right bound, $1C=up bound, $1D=down bound (TILE units; 0x80 = no-clamp).
   $93 = X subtile 0..0x0F, $96 = Y subtile 0..0x0F. $52/$54 = scratch.
   $0197 = actor index (abs $7E0197). $0A00,X / $0A80,X = actor on-screen X / Y (abs). */

void clamp_99DE(void) {
    /* ---- X axis ---- */
    int8_t vx = (int8_t)MEM[0x2E];
    if (vx != 0) {
        if (vx > 0) {                              /* 99E2 BMI not taken */
            uint8_t mag = (uint8_t)vx >> 4;        /* 99E4: LSR x4 */
            if (leaf_right(mag)) MEM[0x2E] = 0;    /* 99E8 JSR 9A60; 99EB BCC->free; 99ED STZ */
            /* 99EF BRA $99FF — NO fall-through to left */
        } else {                                   /* 99F1: negative */
            uint8_t mag = (uint8_t)((~(uint8_t)vx) + 1) >> 4;  /* EOR #$FF; INC; LSR x4 = (-vx)>>4 */
            if (leaf_left(mag)) MEM[0x2E] = 0;     /* 99F8 JSR 9A7E; 99FB BCC->free; 99FD STZ */
        }
    }
    /* ---- Y axis (NOTE the deliberate fall-through, see below) ---- */
    int8_t vy = (int8_t)MEM[0x30];
    if (vy == 0) return;                           /* 9A01 BEQ $9A1E */
    uint8_t A;                                     /* models the 65816 A register across the fall-through */
    if (vy > 0) {                                  /* 9A03 BMI not taken */
        A = (uint8_t)vy >> 4;                      /* 9A05 LSR x4 -> mag */
        bool blocked = leaf_down(A, &A);           /* 9A09 JSR 9A1F; A := leaf's exit-A (see leaf) */
        if (!blocked) return;                      /* 9A0C BCC $9A1E */
        MEM[0x30] = 0;                             /* 9A0E STZ $30  (down blocked) */
        /* FALLS INTO the up branch at 9A10 with the STALE A from leaf_down's exit. */
    } else {
        A = (uint8_t)vy;                           /* enter 9A10 with A = vy (the BMI landed here) */
    }
    /* 9A10: up branch */
    A = (uint8_t)((~A) + 1) >> 4;                  /* EOR #$FF; INC; LSR x4 */
    if (leaf_up(A)) MEM[0x30] = 0;                 /* 9A17 JSR 9A3D; 9A1A BCC->free; 9A1C STZ */
    /* 9A1E RTS */
}

/* ============ LEAVES — return true == CARRY SET == "blocked" ============ */

/* C0/9A60 RIGHT (X+). 'exit-A' is unused by caller (X path BRAs). */
bool leaf_right(uint8_t mag) {
    MEM[0x52] = mag;                               /* 9A60 STA $52 */
    uint8_t footTile = MEM[0x0C] >> 1;             /* 9A62 LDA $0C; LSR */
    if (footTile < MEM[0x1B]) {                    /* 9A65 CMP $1B; 9A67 BCC -> case3 */
        return (0x80 >= MEM[0x0A00 + MEM[0x0197]]);/* 9A75 LDA #$80; CMP $0A00,X -> C=(screenX<=0x80) */
    }
    if (footTile != MEM[0x1B]) return true;        /* 9A69 BNE -> 9A73 SEC (past bound: blocked) */
    return ((MEM[0x93] + mag) >= 0x10);            /* 9A6B ADC $52; CMP #$10 -> C=cross-tile */
}

/* C0/9A1F DOWN (Y+). Returns blocked AND reports exit-A (matters for the fall-through). */
bool leaf_down(uint8_t mag, uint8_t *exitA) {
    MEM[0x52] = mag;                               /* 9A1F STA $52 */
    uint8_t footTile = MEM[0x10] >> 1;             /* 9A21 LDA $10; LSR */
    if (footTile < MEM[0x1D]) {                    /* 9A24 CMP $1D; 9A26 BCC -> case3 */
        *exitA = 0x88;                             /* 9A34 LDA #$88 (A on exit) */
        return (0x88 >= MEM[0x0A80 + MEM[0x0197]]);/* CMP $0A80,X -> C=(screenY<=0x88) */
    }
    if (footTile != MEM[0x1D]) { *exitA = footTile; return true; } /* 9A28 BNE 9A32 SEC */
    *exitA = (uint8_t)(MEM[0x96] + mag);           /* 9A2D ADC $52 (A on exit) */
    return ((MEM[0x96] + mag) >= 0x10);            /* 9A2F CMP #$10 -> carry */
}

/* C0/9A7E LEFT (X-). */
bool leaf_left(uint8_t mag) {
    MEM[0x54] = mag;                               /* 9A7E STA $54 */
    uint8_t footTile = MEM[0x0A] >> 1;             /* 9A80 LDA $0A; LSR */
    MEM[0x52] = footTile;                          /* 9A83 STA $52 */
    if (MEM[0x1A] < footTile) {                    /* 9A85 LDA $1A; CMP $52; 9A89 BCC -> case3 */
        return (MEM[0x0A00 + MEM[0x0197]] >= 0x80);/* 9A99 LDA $0A00,X; CMP #$80 -> C=(screenX>=0x80) */
    }
    if (MEM[0x1A] != footTile) return true;        /* 9A8B BNE -> 9A94 SEC (foot past left: blocked) */
    return ((int8_t)((int8_t)MEM[0x93] - (int8_t)mag) < 0); /* 9A90 SBC $54; 9A92 BPL=free -> blocked if <0 */
}

/* C0/9A3D UP (Y-). */
bool leaf_up(uint8_t mag) {
    MEM[0x54] = mag;                               /* 9A3D STA $54 */
    uint8_t footTile = MEM[0x0E] >> 1;             /* 9A3F LDA $0E; LSR */
    MEM[0x52] = footTile;                          /* 9A42 STA $52 */
    if (MEM[0x1C] < footTile) {                    /* 9A44 LDA $1C; CMP $52; 9A48 BCC -> case3 */
        return (MEM[0x0A80 + MEM[0x0197]] >= 0x88);/* 9A58 LDA $0A80,X; CMP #$88 -> C=(screenY>=0x88) */
    }
    if (MEM[0x1C] != footTile) return true;        /* 9A4A BNE -> 9A53 SEC */
    return ((int8_t)((int8_t)MEM[0x96] - (int8_t)mag) < 0); /* 9A4F SBC $54; 9A51 BPL=free */
}

